using System;using System.Data;using System.Data.SqlClient;namespace StudentAttendanceSystemVS2012{static class ExactLoginTest{static int Main(){try{var db=new Database();var t=db.Query("SELECT u.UserId,u.Username,u.PasswordHash,u.FullName,u.Role,t.TeacherId FROM Users u LEFT JOIN Teachers t ON t.UserId=u.UserId WHERE u.Username=@u AND u.IsActive=1",new SqlParameter("@u","admin"));Console.WriteLine("Rows="+t.Rows.Count);if(t.Rows.Count>0)Console.WriteLine("Verify="+PasswordHasher.Verify("Admin@123",Convert.ToString(t.Rows[0]["PasswordHash"])));return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}}
